class Model(nn.Module):
    def __init__(self, input_shape, reduction):
        super().__init__()
        self.reduction = reduction

    def forward(self, x):
        mask = torch.any(x, dim=1, keepdim=True)
        mask = torch.logical_or(mask, mask.flip(dims=[2]))
        return torch.where(mask, x, torch.tensor(0.0))


