        super().__init__()
        self.norm = nn.BatchNorm1d(num_features, eps=eps, momentum=momentum, affine=affine)

    def forward(self, x):
        # torch.triu only applies to 2D tensor
        # to make the operation meaningful in the context of BatchNorm1d,
